  /* =====================================================================================
     reference.js: the desk's knowledge base. Glossary, methods, hard questions, model risk,
     data dictionary, episode atlas, reading list, checklists, playbooks, signals, changelog.
     Everything here is static content; live numbers come from data/*.json at runtime.
     ===================================================================================== */

  // id becomes the anchor g-<id>; at is the element id where the idea is used on the site
  const GLOSSARY = [
    { id: "bp", term: "Basis point", alt: ["bp"], def: "One hundredth of a percentage point: 0.01%. Yields and spreads move in basis points.", at: "rates-title" },
    { id: "par-yield", term: "Par yield", def: "The coupon at which a bond prices at exactly 100. The Treasury's daily curve is a par curve.", at: "rates-title" },
    { id: "yield-curve", term: "Yield curve", alt: ["curve"], def: "Yields across maturities on one date. Upward sloping is normal; inverted, with short yields above long, has preceded recessions.", at: "rates-title" },
    { id: "duration", term: "Duration", alt: ["modified duration"], def: "Percent price change for a one-point move in yield, sign flipped. A duration of 15 means about −15% for a 1% rise in yield.", why: "The single most important number in a bond hedge.", at: "bc-title" },
    { id: "macaulay", term: "Macaulay duration", def: "The present-value-weighted average time to a bond's cash flows. Modified duration is Macaulay divided by (1 + y/2).", at: "bc-title" },
    { id: "convexity", term: "Convexity", def: "How duration changes as yields move. Positive convexity means a bond gains more when yields fall than it loses when they rise by the same amount.", why: "Long bonds and long options are convex; that asymmetry is what a hedge buys.", at: "bc-title" },
    { id: "dv01", term: "DV01", alt: ["dollar value of a basis point"], def: "The dollar gain or loss on a position when yields move one basis point.", why: "Hedges are matched in DV01, not in notional.", at: "ct-title" },
    { id: "steepener", term: "Steepener", alt: ["flattener", "bull steepener", "bear flattener"], def: "A curve trade that profits when the long-minus-short spread widens; a flattener profits when it narrows. Bull and bear say whether yields are falling or rising.", at: "ct-title" },
    { id: "2s10s", term: "2s10s", def: "The 10-year Treasury yield minus the 2-year, in basis points. The most-watched measure of curve slope.", at: "spread-tiles" },
    { id: "real-yield", term: "Real yield", def: "Yield after inflation, read from TIPS.", why: "In 2026, real yields did the tightening.", at: "decomp" },
    { id: "breakeven", term: "Breakeven inflation", alt: ["breakeven", "breakevens"], def: "The nominal Treasury yield minus the TIPS real yield at the same maturity: the inflation rate at which the two pay the same.", at: "decomp" },
    { id: "tips", term: "TIPS", def: "Treasury Inflation-Protected Securities: principal indexed to CPI, so they pay a real yield.", at: "sec-tips" },
    { id: "term-premium", term: "Term premium", def: "Extra yield investors demand to hold a long bond instead of rolling short bills. Estimated by models: Kim-Wright on FRED, ACM at the New York Fed.", why: "A rising term premium is how stocks and bonds fall together.", at: "rates-title" },
    { id: "forward-rate", term: "Forward rate", alt: ["forward", "forwards", "5y5y"], def: "The rate for a future period locked in today, implied by the curve. The 5y5y is the 5-year rate starting 5 years from now.", at: "fw-title" },
    { id: "zero-rate", term: "Zero rate", alt: ["spot rate", "zero curve"], def: "The yield on a single cash flow at one date, bootstrapped from par yields. The building block for forwards.", at: "fw-title" },
    { id: "carry", term: "Carry", def: "What a position earns if prices do not move. For a financed bond: its coupon minus the financing rate.", at: "fw-title" },
    { id: "roll-down", term: "Roll-down", def: "The price gain as a bond ages into a lower-yielding part of an upward-sloping curve.", at: "fw-title" },
    { id: "breakeven-move", term: "Breakeven yield move", def: "How far yields can rise over the holding period before carry and roll-down are used up.", at: "fw-title" },
    { id: "cmt", term: "Constant maturity yield", def: "The Treasury's interpolated yield at a fixed maturity (DGS10 is the 10-year). The engine rebuilds bond returns from these.", at: "dict-title" },
    { id: "bill", term: "Treasury bill", alt: ["T-bills", "bills"], def: "Treasury debt maturing within a year, sold at a discount. The safe leg of a barbell.", at: "sec-treasury-bills" },
    { id: "ctd", term: "Cheapest to deliver", alt: ["CTD"], def: "The bond a futures seller will deliver because it costs least after the conversion factor. Futures track its price and DV01.", at: "fut-title" },
    { id: "conversion-factor", term: "Conversion factor", def: "CME's multiplier that puts every deliverable bond on a common footing: the bond's price at a 6% yield.", at: "fut-title" },
    { id: "treasury-futures", term: "Treasury futures", def: "Exchange-traded contracts on notes and bonds (ZN, TN, ZB, UB). They add or remove duration for margin instead of cash.", at: "fut-title" },
    { id: "basis-trade", term: "Basis trade", def: "Long cash Treasuries, short futures, financed in repo and run at high leverage. Its unwinds can make Treasuries fall in a crisis, as in March 2020.", at: "ep-covid-2020" },
    { id: "repo", term: "Repo", def: "A collateralized short-term loan against securities; the financing rate for levered bond positions.", at: "fw-title" },
    { id: "sofr", term: "SOFR", def: "The Secured Overnight Financing Rate: what it costs to borrow cash overnight against Treasuries.", at: "liq-title" },
    { id: "iorb", term: "IORB", alt: ["interest on reserve balances"], def: "The rate the Fed pays banks on their reserves. Repo trading above it means cash is scarce.", at: "liq-title" },
    { id: "reserves", term: "Bank reserves", alt: ["reserves"], def: "Banks' deposits at the Fed, the system's settlement cash. When they get scarce, repo rates jump, as in September 2019.", at: "liq-title" },
    { id: "tga", term: "Treasury General Account", alt: ["TGA"], def: "The Treasury's cash account at the Fed. When it rises on tax receipts or new debt, bank reserves fall, all else equal.", at: "liq-title" },
    { id: "rrp", term: "Overnight reverse repo", alt: ["reverse repo", "ON RRP"], def: "A Fed facility where money funds park cash overnight. It held more than $2 trillion in 2022 and is now nearly empty, so drains come out of bank reserves.", at: "liq-title" },
    { id: "net-liquidity", term: "Net liquidity", def: "Fed assets minus the Treasury General Account minus overnight reverse repo: a rough measure of the cash the Fed leaves in the private system.", at: "liq-title" },
    { id: "qt", term: "Quantitative tightening", alt: ["QT"], def: "The Fed shrinking its balance sheet by letting bonds mature without reinvesting. It ended on Dec 1, 2025.", at: "liq-title" },
    { id: "credit-spread", term: "Credit spread", alt: ["spreads"], def: "Extra yield over Treasuries that pays for default and liquidity risk.", at: "rates-live-sec" },
    { id: "oas", term: "OAS", alt: ["option-adjusted spread"], def: "Option-adjusted spread: the credit spread after stripping out embedded options. The ICE BofA indices on FRED report it.", at: "rates-live-sec" },
    { id: "high-yield", term: "High yield", alt: ["junk"], def: "Bonds rated below BBB−.", at: "sec-high-yield-bonds" },
    { id: "ccc", term: "CCC spread", def: "The option-adjusted spread on the lowest-rated junk bonds, CCC and below: where credit stress shows first.", at: "signals" },
    { id: "investment-grade", term: "Investment grade", def: "Bonds rated BBB− or better.", at: "sec-investment-grade-corporates" },
    { id: "cds", term: "Credit default swap", alt: ["CDS"], def: "Insurance on a borrower's default, paid as an annual spread.", at: "sec-credit-default-swaps" },
    { id: "private-credit", term: "Private credit", def: "Loans made by funds and insurers instead of banks, held to maturity and marked by models.", at: "pc-title" },
    { id: "clo", term: "CLO", alt: ["collateralized loan obligation"], def: "A pool of leveraged loans cut into tranches from AAA to equity.", at: "sec-clos" },
    { id: "bdc", term: "BDC", alt: ["business development company"], def: "A listed vehicle that holds private loans. Its discount to book value is a real-time read on private credit marks.", at: "t6" },
    { id: "beta", term: "Beta", def: "A return's sensitivity to a factor. A market beta of 1.2 means about 1.2% for each 1% the market moves.", at: "fut-title" },
    { id: "factor", term: "Factor", def: "A common driver of returns. The engine uses three: market (QQQ), AI (the basket minus QQQ) and rates (TLT).", at: "eng-title" },
    { id: "fcf", term: "Free cash flow", def: "Operating cash flow minus capital expenditure.", at: "capex-live-sec" },
    { id: "capex", term: "Capex", alt: ["capital expenditure"], def: "Spending on long-lived assets: data centers, chips, power.", at: "capex-live-sec" },
    { id: "depreciation", term: "Depreciation", def: "Capex expensed over an asset's useful life. Stretching assumed server lives lowers reported expense, which is Burry's point.", at: "lens-michael-burry" },
    { id: "hyperscaler", term: "Hyperscaler", alt: ["hyperscalers"], def: "A company running cloud data centers at the largest scale: Amazon, Microsoft, Alphabet, Meta, Oracle.", at: "t1" },
    { id: "call-put", term: "Call and put", alt: ["call", "put", "puts", "calls"], def: "A call is the right to buy at the strike; a put is the right to sell.", at: "bs-title" },
    { id: "strike", term: "Strike", def: "The price at which an option can be exercised.", at: "bs-title" },
    { id: "implied-vol", term: "Implied volatility", alt: ["implied vol"], def: "The volatility that makes Black-Scholes match an option's market price: the market's price of future movement.", at: "bs-title" },
    { id: "realized-vol", term: "Realized volatility", def: "How much a price actually moved, annualized. Implied minus realized is the volatility risk premium that option sellers earn.", at: "iv-title" },
    { id: "vrp", term: "Volatility risk premium", alt: ["volatility premium"], def: "Implied minus realized volatility: what buyers of protection pay sellers, on average, for carrying crash risk. Usually positive; negative in a crash, when realized outruns implied.", why: "The price of insurance relative to the risk it covers.", at: "iv-title" },
    { id: "vix-term", term: "VIX term structure", alt: ["contango", "backwardation"], def: "VIX against longer-dated implied volatility such as the 3-month VIX. Normally upward sloping (contango); inverted (backwardation) when fear is concentrated in the next month.", at: "iv-title" },
    { id: "vxn", term: "VXN", def: "Cboe's Nasdaq-100 volatility index: the VIX for the index this book tracks.", at: "iv-title" },
    { id: "black-scholes", term: "Black-Scholes", def: "The 1973 option-pricing model, here with a dividend yield. It assumes one constant volatility, which skew contradicts.", at: "bs-title" },
    { id: "delta", term: "Delta", def: "Option price change per $1 move in the underlying.", at: "bs-title" },
    { id: "gamma", term: "Gamma", def: "How fast delta changes as the underlying moves. Long options are long gamma: they gain from large moves either way.", at: "bs-title" },
    { id: "vega", term: "Vega", def: "Option price change per one-point change in implied volatility.", at: "bs-title" },
    { id: "theta", term: "Theta", def: "Option value lost per day as expiry approaches, all else equal: the rent on convexity.", at: "bs-title" },
    { id: "skew", term: "Skew", def: "Out-of-the-money puts trade at higher implied volatility than at-the-money options, because crashes are what investors pay to insure.", at: "tb-title" },
    { id: "put-spread", term: "Put spread", alt: ["put spreads"], def: "Long a put, short a lower-strike put: cheaper insurance with a capped payout.", at: "po-title" },
    { id: "collar", term: "Collar", alt: ["collars"], def: "A long put paid for by selling a call: protection funded with upside.", at: "po-title" },
    { id: "covered-call", term: "Covered call", def: "Long the stock, short a call: income that gives away upside and keeps the downside.", at: "po-title" },
    { id: "vix", term: "VIX", def: "The S&P 500's 30-day implied volatility, from listed options. Above 30 is stress; below 15 is calm, when protection is cheap.", at: "sig-title" },
    { id: "tail-hedge", term: "Tail hedge", def: "Protection that pays only in large drawdowns, run as a standing yearly budget.", at: "tb-title" },
    { id: "barbell", term: "Barbell", def: "Taleb's shape: most capital very safe, a small part in very convex bets, little in the fragile middle.", at: "po-title" },
    { id: "spot-vol-grid", term: "Spot-vol grid", def: "Position P&L across moves in the underlying and in implied volatility: how an options desk reads its risk.", at: "grid-title" },
    { id: "correlation", term: "Correlation", def: "How closely two return series move together, from −1 to +1.", at: "regime-title" },
    { id: "stock-bond", term: "Stock-bond correlation", def: "The correlation of stock and bond returns. Negative means bonds hedge stocks. It was negative from about 2000 until 2021 and has been near zero or positive since.", why: "The variable the whole desk is built around.", at: "regime-title" },
    { id: "ewma", term: "EWMA", alt: ["exponentially weighted"], def: "Exponentially weighted moving average: recent days count more. With a 63-day half-life a day's weight halves every 63 trading days.", at: "eng-title" },
    { id: "hysteresis", term: "Hysteresis", def: "A switch that needs a bigger move to change state than to stay in it, so the regime label does not flicker around zero.", at: "eng-title" },
    { id: "regime", term: "Regime", def: "The engine's state for the stock-bond relationship: hedging, neutral or amplifying.", at: "live" },
    { id: "min-var", term: "Minimum-variance hedge ratio", alt: ["min-variance"], def: "The hedge size that minimizes the variance of book plus hedge: minus their covariance over the hedge's variance.", at: "hedge" },
    { id: "rho-squared", term: "ρ² rule", def: "A hedge can remove at most the squared correlation of a book's variance: 9% at a −0.3 correlation, 49% at −0.7.", at: "lanes-title" },
    { id: "var", term: "Value at risk", alt: ["VaR"], def: "The loss not exceeded on a given share of days. A 99% one-day VaR is the 1-in-100-days loss.", at: "live" },
    { id: "es", term: "Expected shortfall", def: "The average loss on days worse than VaR: what the tail actually costs.", at: "live" },
    { id: "fhs", term: "Filtered historical simulation", def: "Historical returns rescaled by today's volatility forecast, so VaR responds to current conditions.", at: "live" },
    { id: "drawdown", term: "Drawdown", def: "The fall from a portfolio's peak to its trough.", at: "size" },
    { id: "vol-target", term: "Volatility targeting", alt: ["vol targeting", "vol target"], def: "Scaling exposure so forecast volatility hits a target: less exposure when markets are wild.", at: "size" },
    { id: "kelly", term: "Kelly criterion", alt: ["Kelly"], def: "The bet size that maximizes long-run growth: expected excess return over variance. Fractional Kelly bets less because the edge is uncertain.", at: "size" },
    { id: "gross-net", term: "Gross exposure", alt: ["gross"], def: "Longs plus shorts as a share of capital. Net is longs minus shorts.", at: "size" },
    { id: "beta-adjusted", term: "Beta-adjusted exposure", def: "Exposure scaled by beta: what the book's dollars are worth in index terms.", at: "fut-title" },
    { id: "stress-test", term: "Stress test", def: "Revaluing the book under a historical or hypothetical shock.", at: "hedge" },
    { id: "ergodicity", term: "Ergodicity", def: "Whether a strategy's average across many people equals its average over time for one person. With ruin possible it does not, which is why the desk sizes for survival.", at: "lens-nassim-taleb" },
    { id: "fat-tails", term: "Fat tails", def: "Extreme moves far more often than a normal distribution predicts.", at: "lens-nassim-taleb" },
    { id: "sharpe", term: "Sharpe ratio", alt: ["Sharpe"], def: "Excess return per unit of volatility, annualized.", at: "live" },
    { id: "deflated-sharpe", term: "Deflated Sharpe ratio", alt: ["deflated Sharpe"], def: "The probability that a Sharpe ratio is real after charging for the number of strategies tried and for skew and fat tails (Bailey and López de Prado).", at: "live" },
    { id: "look-ahead", term: "Look-ahead bias", alt: ["look-ahead"], def: "Using information in a backtest that was not available at the time.", why: "The engine's canary test fails the build if timing ever leaks.", at: "eng-title" },
    { id: "walk-forward", term: "Walk-forward test", alt: ["walk-forward"], def: "Fit on the past, test on the next period, roll forward. Purging removes overlap so a test never sees its own training data.", at: "eng-title" },
    { id: "brier", term: "Brier score", def: "Mean squared error of probability forecasts. The skill score compares it with always forecasting the base rate.", at: "eng-title" },
    { id: "auc", term: "AUC", def: "The probability a model ranks a random positive case above a random negative one; 0.5 is a coin flip.", at: "eng-title" },
    { id: "overfitting", term: "Backtest overfitting", def: "Picking the best of many trials and mistaking luck for skill.", at: "eng-title" },
    { id: "float", term: "Float", def: "Premiums an insurer holds before paying claims: money it invests but does not own.", at: "how-title" },
    { id: "solvency-ii", term: "Solvency II ratio", def: "A European insurer's available capital over required capital; above 100% meets the rule.", at: "cos-title" },
    { id: "all-weather", term: "All Weather", def: "Bridgewater's risk-balanced portfolio, built to hold up across growth and inflation surprises.", at: "regime-title" },
    { id: "reflexivity", term: "Reflexivity", def: "Soros's idea that prices feed back into the fundamentals they reflect.", at: "lens-george-soros" },
    { id: "prediction-market", term: "Prediction market", alt: ["prediction markets"], def: "Contracts that pay $1 if an event happens; the price reads as a probability.", at: "sec-prediction-markets" },
    { id: "carry-trade", term: "Carry trade", def: "Borrowing in a low-yielding currency, often the yen, to buy higher-yielding assets. It earns slowly and unwinds fast, as in August 2024.", at: "ep-carry-2024" },
    { id: "z-score", term: "Z-score", alt: ["standard deviations"], def: "How many standard deviations a move sits from the average. Under a normal distribution a 2σ week comes about once in 22; fat tails make it more common.", at: "mv-title" },
    { id: "fwd-inflation", term: "5y5y inflation expectation", def: "The breakeven inflation rate for the five years starting five years from now. The Fed reads it as long-run inflation credibility.", at: "levels-title" },
    { id: "velocity", term: "Velocity", alt: ["rate of change", "rates of change"], def: "How fast a series moves: the least-squares slope of its last 13 weeks of prints, per week (three months for monthly data).", at: "roc-title" },
    { id: "acceleration", term: "Acceleration", alt: ["second derivative"], def: "Whether the move is speeding up: today's 13-week velocity minus the velocity 13 weeks ago.", at: "roc-title" },
    { id: "time-to-trigger", term: "Time to trigger", def: "Distance to a rule's line divided by the velocity, when the market is moving toward it: when the rule fires if the pace holds.", at: "roc-title" },
    { id: "hedge-line", term: "Inflation hedge line", alt: ["hedge line"], def: "Since 1871, with three-year inflation above about 2.75 to 4.25%, stocks and bonds have mostly moved together. Chosen on data through 2016 only and tested on the decade after, the line is 4.25%; a bootstrap puts it anywhere from 2.75% to 4.25%.", at: "fi-title" },
    { id: "evidence-label", term: "Evidence label", alt: ["observed", "estimated", "assumed", "hypothesis"], def: "Every number carries one: Observed (a published print), Estimated (a model fit to data), Assumed (an input someone chose), Historical pattern, Hypothesis (a claim to test), or Unavailable.", at: "today7" },
    { id: "posterior", term: "Posterior", alt: ["bayes", "bayesian update"], def: "The probability of each scenario after the evidence: prior times the likelihood of what was observed, normalized. Signals that share a driver are averaged so one cause counts once.", at: "solve-title" },
    { id: "evsi", term: "Value of information", alt: ["EVSI", "EVPI"], def: "How much better the decision gets, on average, from learning a signal before acting, in basis points of certainty-equivalent return. Perfect foresight (EVPI) is the ceiling.", at: "rzv-title" },
    { id: "reverse-stress", term: "Reverse stress test", def: "The most plausible joint move of the risk factors that produces a given loss: the point on the loss boundary closest to today in Mahalanobis distance.", at: "rzr-title" },
    { id: "nash", term: "Nash equilibrium", alt: ["equilibrium", "best response"], def: "A set of choices where no player gains by changing theirs alone. It need not be good for anyone: the capex race and the crowded exit are both equilibria.", at: "games-title" },
    { id: "cournot", term: "Cournot competition", def: "Firms choose quantities; the price falls with the total. Each firm ignores the price cut it imposes on the others, so the industry overbuilds: 2N/(N+1) times the joint-profit quantity.", at: "gtc-title" },
    { id: "global-game", term: "Global game", alt: ["Morris-Shin"], def: "A coordination game with noisy private information. It turns a bank run's multiple equilibria into one threshold: below it, everyone runs.", at: "gtx-title" },
    { id: "kyle-lambda", term: "Kyle's lambda", def: "Price impact per unit of net order flow when a market maker cannot tell informed from uninformed traders: σ<sub>v</sub>/(2σ<sub>u</sub>).", at: "gtk-title" },
    { id: "markout", term: "Markout", def: "Signed price move after a fill, measured from the fill price to the midpoint some time later: the edge at the fill plus the move after it.", at: "fq-title" },
    { id: "frechet", term: "Fréchet bounds", def: "The range a joint probability can take without assuming independence: from max(0, Σp − (n − 1)) to min p.", at: "as-title" },
    { id: "eff-bets", term: "Effective independent bets", alt: ["effective bets", "effective risk contributors"], def: "Two different counts. Effective risk contributors = 1/Σ(risk share²) by position; effective independent bets = exp(entropy) of risk across principal components. Two perfectly correlated positions score 2 and 1.", at: "pol-title" },
    { id: "base-effect", term: "Base effect", alt: ["base effects"], def: "A change in an average or a yearly rate caused by which months drop out of the window, not by what happens now.", at: "dec-title" },
    { id: "minsky", term: "Minsky stages", alt: ["hedge finance", "speculative finance", "Ponzi finance"], def: "Hyman Minsky's three borrowing postures: cash flow covers everything (hedge), covers interest only (speculative), or neither (Ponzi).", at: "mi-title" },
    { id: "nonop", term: "Non-operating income", alt: ["paper profits"], def: "Income outside the business: gains on investments, interest and the like. For the builders, mostly marks on stakes in other AI companies.", at: "pp-title" },
    { id: "rpo", term: "Remaining performance obligations", alt: ["RPO"], def: "Revenue already contracted but not yet recognized: the reported backlog.", at: "bl-title" },
    { id: "useful-life", term: "Useful life", alt: ["server life", "server lives"], def: "The years over which an asset is depreciated. A longer life lowers each year's depreciation and raises reported earnings.", at: "dw-title" },
    { id: "conjunction", term: "Conjunction", def: "All of several things being true at once. Its probability is the product of theirs when they are independent.", at: "as-title" },
    { id: "fragility", term: "Fragility", def: "The desk's ranking of an assumption: (1 − probability) × impact. High fragility is likely to fail and costly when it does.", at: "as-title" },
    { id: "known-unknowns", term: "Known unknowns", alt: ["unknown unknowns", "known knowns", "unknown knowns"], def: "The four quadrants of what we know and know we know, each with its own response: act, size the range, audit, or prepare.", at: "kk-title" },
    { id: "second-order", term: "Second-order thinking", alt: ["second order", "fourth order"], def: "Following a shock past its first effect to what that effect forces others to do, and what that forces in turn.", at: "ch-title" },
    { id: "calibration", term: "Calibration", def: "Whether the things you call 70% likely happen 70% of the time. Scored with the Brier score and a calibration chart.", at: "jrs-title" },
    { id: "alpha", term: "Alpha", def: "Return after the market's share: return minus beta times the benchmark's return.", at: "jrs-title" },
    { id: "aar", term: "After-action review", def: "The US Army's debrief: what was supposed to happen, what did, why, and what to sustain or improve.", at: "jr-title" },
    { id: "pre-mortem", term: "Pre-mortem", def: "Imagining a decision has already failed and writing down why, before making it.", at: "jr-title" },
    { id: "black-swan", term: "Black swan", alt: ["black swans", "gray swan", "gray swans"], def: "Taleb's term for a rare, extreme event that is explained only after the fact. A gray swan is one that can be named in advance.", at: "atlas-title" },
    { id: "tail-index", term: "Tail index", alt: ["Hill estimator"], def: "How fast extreme losses thin out. Moments of order α and above do not exist; stock returns sit near 2 to 3.", at: "tails-title" },
    { id: "cape", term: "CAPE", alt: ["cyclically adjusted P/E"], def: "Shiller's price over ten years of average real earnings. High readings have preceded low ten-year returns.", at: "fi-title" },
    { id: "capacity-price", term: "Capacity price", alt: ["capacity auction"], def: "What a grid operator pays generators to be available in a future year. PJM's has cleared at its cap twice.", at: "gr-title" },
    { id: "megaproject", term: "Megaproject", alt: ["megaprojects"], def: "A project costing a billion dollars or more. Flyvbjerg's data: 8.5% finish on time and on budget.", at: "mp-title" },
    { id: "lindy", term: "Lindy effect", def: "For ideas and institutions, every year survived adds to the expected remaining life.", at: "tal-title" },
    { id: "volatility-drag", term: "Volatility drag", def: "Compound growth falls short of the average return by about half the variance.", at: "lab-title" },
    { id: "likelihood-ratio", term: "Likelihood ratio", def: "How much more often a signal fires when the event is coming than when it is not: the factor by which it moves the odds.", at: "lab-title" },
    { id: "desk-read", term: "Desk read", def: "The one-line summary above the signals board: how many signals are red or amber, and which playbook they argue for.", at: "signals" },
    { id: "avellaneda-stoikov", term: "Avellaneda-Stoikov", def: "A market maker's optimal quotes: shade the mid by inventory times risk aversion times variance, and quote a spread that pays for both inventory risk and the depth of the book.", at: "mmas-title" },
    { id: "adverse-selection", term: "Adverse selection", def: "Losing to counterparties who know more. A market maker's spread must cover what informed traders take (Glosten and Milgrom).", at: "gm-title" },
    { id: "square-root-law", term: "Square-root impact", alt: ["square-root law"], def: "Market impact grows with the square root of order size relative to daily volume: four times the size, twice the impact per share.", at: "ex-title" },
    { id: "almgren-chriss", term: "Almgren-Chriss", def: "The optimal schedule for working a large order: trade faster to cut timing risk, slower to cut impact; the urgency parameter sets the balance.", at: "ex-title" },
    { id: "internalization", term: "Internalization", alt: ["off-exchange"], def: "Filling orders against a dealer's own book instead of on an exchange. About half of US share volume now trades off exchange.", at: "mms-title" },
    { id: "zero-dte", term: "0DTE", alt: ["same-day options"], def: "Options that expire the day they trade. Two thirds of S&P 500 option volume in July 2026.", at: "mms-title" },
    { id: "expectancy", term: "Expectancy", def: "Average profit per trade in units of risk (R): win rate times average win, minus loss rate times average loss, minus costs.", at: "pe-title" },
    { id: "funded-challenge", term: "Funded-account challenge", alt: ["prop challenge"], def: "A paid evaluation: hit a profit target before breaching a daily or total loss limit to trade the firm's capital.", at: "chal-title" },
    { id: "pass-through", term: "Pass-through fees", def: "Costs a multi-manager fund charges investors on top of fees: PM pay, data, technology. 3 to 10% of NAV a year.", at: "pr-pods-title" },
    { id: "leontief", term: "Leontief inverse", def: "The total effect of a shock through every chain of links in a network, (I − W)⁻¹: the sum of first, second, third and higher-order effects.", at: "brw-title" },
    { id: "spectral-radius", term: "Spectral radius", def: "The largest eigenvalue size of a network's link matrix. Below 1, shocks fade as they travel; at or above 1, some loop feeds on itself.", at: "brw-title" },
    { id: "feedback-loop", term: "Feedback loop", alt: ["reinforcing loop", "balancing loop"], def: "A chain of links that returns to where it started. A positive product of the links reinforces a shock; a negative one damps it.", at: "brw-title" },
    { id: "dated-brent", term: "Dated Brent", def: "The price of physical North Sea cargoes loading soon. It traded about $27 over Brent futures in October 2026: the physical market is tighter than the futures say.", at: "nwc-title" },
    { id: "pik", term: "PIK", alt: ["payment in kind"], def: "Interest paid with more debt instead of cash. Rising PIK, above all amended after the loan was made, is a disguised default.", at: "bs-credit-title" },
    { id: "reverse-dcf", term: "Reverse DCF", def: "Solving for the growth a price already assumes, instead of the price a forecast implies.", at: "bsc-title" },
    { id: "cash-eps", term: "Cash EPS", def: "Earnings per share after setting depreciation to economic life, counting stock pay as pay, expensing capitalized software and crediting deferred revenue.", at: "bsc-title" },
    { id: "moonbag", term: "Moonbag", def: "What is left of a winner after selling enough to recover the original cost: a free position on the right tail.", at: "bsz-title" },
    { id: "student-t", term: "Student-t", def: "A bell-shaped distribution with fat tails. Fitted to 155 years of monthly stocks, it has about 3.8 degrees of freedom.", at: "bst-title" },
    { id: "heat-score", term: "Heat score", alt: ["niche skew"], def: "How unusual today's mentions of a theme are against its last 28 days; niche skew is how much of the talk comes from sources few people read.", at: "nws-title" },
  ];

  // formulas render as HTML: <var> for symbols, <sub>/<sup>, .frac for fractions
  const METHODS = [
    { group: "Bonds", items: [
      { name: "Price", f: "<var>P</var> = Σ<sub>k=1..n</sub> 100 · (<var>c</var>/2) · (1 + <var>y</var>/2)<sup>−k</sup> + 100 · (1 + <var>y</var>/2)<sup>−n</sup>, &nbsp; <var>n</var> = 2<var>T</var>", say: "Semiannual coupons discounted at the yield. Every bond on the site is repriced this way, never approximated.", where: "bonds.py · Bond calculator" },
      { name: "Duration and convexity", f: "<var>D</var> = [<var>P</var>(<var>y</var>−<var>h</var>) − <var>P</var>(<var>y</var>+<var>h</var>)] / (2<var>Ph</var>), &nbsp; <var>C</var> = [<var>P</var>(<var>y</var>+<var>h</var>) + <var>P</var>(<var>y</var>−<var>h</var>) − 2<var>P</var>] / (<var>Ph</var><sup>2</sup>), &nbsp; <var>h</var> = 1bp", say: "Central differences around the yield. Price change ≈ −<var>D</var>Δ<var>y</var> + ½<var>C</var>(Δ<var>y</var>)<sup>2</sup>.", where: "bonds.py · Bond calculator" },
      { name: "DV01", f: "DV01 = <var>D</var> × (<var>P</var>/100) × Face × 0.0001", say: "Dollars per basis point. Bills use <var>D</var> = <var>t</var>/(1 + <var>yt</var>).", where: "Bond calculator · Duration menu" },
      { name: "TLT proxy", f: "one 25.8-year bond, coupon solved so <var>D</var> = 15.5; return = <var>P</var>(<var>y</var><sub>0</sub>+Δ<var>y</var>)/<var>P</var>(<var>y</var><sub>0</sub>) − 1", say: "TLT's weighted maturity and duration, repriced exactly, so convexity is in every scenario.", where: "bonds.py · Hedge lab" },
      { name: "Bond returns from FRED", f: "<var>r</var><sub>t</sub> = <var>P</var>(<var>y</var><sub>t</sub>; 20 − Δ<var>t</var>, <var>c</var> = <var>y</var><sub>t−1</sub>)/100 − 1", say: "Buy a 20-year par bond at yesterday's yield, reprice it at today's. Builds bond returns back to 1993.", where: "bonds.py · macro.py" },
    ] },
    { group: "Curve", items: [
      { name: "Par interpolation", f: "monotone cubic (PCHIP, Fritsch-Carlson) between tenors; flat beyond the 1-month and 30-year points", say: "No overshoot between tenors. Linear interpolation would put a kink at every tenor and turn the forward curve into a saw.", where: "curve.py · math.js parAt" },
      { name: "Bootstrap", f: "DF(<var>t</var>) = [1 − (<var>c</var>/2) Σ<sub>j&lt;t</sub> DF(<var>j</var>)] / (1 + <var>c</var>/2), &nbsp; bills: DF(<var>t</var>) = (1 + <var>y</var>/2)<sup>−2<var>t</var></sup>", say: "Each par bond must price at 100, which pins down one new discount factor per half year.", where: "curve.py · Forwards" },
      { name: "Zero and forward rates", f: "<var>z</var>(<var>t</var>) = 2[DF(<var>t</var>)<sup>−1/(2<var>t</var>)</sup> − 1], &nbsp; <var>f</var>(<var>t</var><sub>1</sub>,<var>t</var><sub>2</sub>) = 2[(DF(<var>t</var><sub>1</sub>)/DF(<var>t</var><sub>2</sub>))<sup>1/(2(<var>t</var><sub>2</sub>−<var>t</var><sub>1</sub>))</sup> − 1]", say: "The 5y5y forward is <var>f</var>(5, 10).", where: "curve.py · Forwards" },
      { name: "Carry and roll-down", f: "<var>R</var> = [<var>P</var>(<var>y</var><sub>T−1</sub>; <var>T</var>−1, <var>c</var>) − 100]/100 + (<var>c</var> − <var>r</var><sub>repo</sub>); breakeven Δ solves <var>R</var>(Δ) = 0", say: "One year, curve unchanged, financed at the 3-month bill. The breakeven is the yield rise the position can absorb.", where: "curve.py · Carry table" },
      { name: "Futures DV01", f: "DV01<sub>fut</sub> ≈ DV01<sub>CTD</sub> / CF, &nbsp; CF = <var>P</var>(6%; <var>T</var> rounded down to a quarter, <var>c</var>)/100", say: "The cheapest to deliver is taken as the shortest deliverable, right while yields sit below 6%.", where: "curve.py · Futures hedge" },
    ] },
    { group: "Options", items: [
      { name: "Black-Scholes with dividends", f: "<var>d</var><sub>1</sub> = [ln(<var>S</var>/<var>K</var>) + (<var>r</var> − <var>q</var> + σ<sup>2</sup>/2)<var>T</var>] / (σ√<var>T</var>), &nbsp; <var>d</var><sub>2</sub> = <var>d</var><sub>1</sub> − σ√<var>T</var>", say: "Call = <var>Se</var><sup>−<var>qT</var></sup><var>N</var>(<var>d</var><sub>1</sub>) − <var>Ke</var><sup>−<var>rT</var></sup><var>N</var>(<var>d</var><sub>2</sub>); put = <var>Ke</var><sup>−<var>rT</var></sup><var>N</var>(−<var>d</var><sub>2</sub>) − <var>Se</var><sup>−<var>qT</var></sup><var>N</var>(−<var>d</var><sub>1</sub>).", where: "options.py · Option pricer" },
      { name: "Greeks", f: "Δ<sub>call</sub> = <var>e</var><sup>−<var>qT</var></sup><var>N</var>(<var>d</var><sub>1</sub>), &nbsp; Γ = <var>e</var><sup>−<var>qT</var></sup>φ(<var>d</var><sub>1</sub>)/(<var>S</var>σ√<var>T</var>), &nbsp; vega = <var>Se</var><sup>−<var>qT</var></sup>φ(<var>d</var><sub>1</sub>)√<var>T</var>/100", say: "Vega per volatility point, theta per calendar day. The normal CDF uses Marsaglia's series, accurate to about 1e−15.", where: "options.py · Option pricer" },
      { name: "Put-call parity", f: "<var>C</var> − <var>P</var> = <var>Se</var><sup>−<var>qT</var></sup> − <var>Ke</var><sup>−<var>rT</var></sup>", say: "Checked in the tests for every strike and tenor.", where: "tests/test_curve_and_options.py" },
      { name: "Implied volatility", f: "σ<sub>imp</sub>: BS(σ) = market price, by bisection on [0.0001, 5]", say: "Returns nothing when the price breaks the no-arbitrage bounds.", where: "options.py · Option pricer" },
      { name: "Tail budget", f: "yearly cost = premium × (365/tenor) × notional; payout = notional × max(<var>K</var> − <var>S</var><sub>T</sub>, 0)", say: "Puts rolled at a fixed moneyness on the whole book.", where: "Tail-hedge budget" },
    ] },
    { group: "Hedging and regime", items: [
      { name: "Minimum-variance hedge", f: "<var>h</var>* = −Cov(<var>r</var><sub>book</sub>, <var>r</var><sub>hedge</sub>) / Var(<var>r</var><sub>hedge</sub>), &nbsp; long-only: max(0, <var>h</var>*)", say: "At <var>h</var>*, the variance removed is exactly ρ<sup>2</sup>.", where: "hedge.py · Engine readout" },
      { name: "EWMA covariance", f: "λ = 0.5<sup>1/<var>H</var></sup>, &nbsp; Cov<sub>t</sub> = λ Cov<sub>t−1</sub> + (1 − λ) <var>x</var><sub>t</sub><var>y</var><sub>t</sub>, &nbsp; <var>H</var> = 63 days", say: "Recent days weigh more; a quarter's half-life.", where: "regime.py" },
      { name: "Regime with hysteresis", f: "hedging once ρ ≤ −0.10, until ρ &gt; 0; amplifying once ρ ≥ +0.10, until ρ &lt; 0; otherwise neutral", say: "The bond hedge is held only in the hedging state.", where: "regime.py · Signals" },
      { name: "Equity futures hedge", f: "contracts = Book × β × share / (index level × multiplier)", say: "NQ is $20 per Nasdaq-100 point, MNQ $2.", where: "Futures hedge" },
      { name: "Rates futures hedge", f: "contracts = Notional × <var>D</var> × 0.0001 / DV01<sub>contract</sub>", say: "Replicates a TLT hedge for margin instead of cash.", where: "hedge.py · Futures hedge" },
    ] },
    { group: "Volatility and sizing", items: [
      { name: "GARCH(1,1)", f: "σ<sup>2</sup><sub>t</sub> = ω + α ε<sup>2</sup><sub>t−1</sub> + β σ<sup>2</sup><sub>t−1</sub>", say: "Volatility clusters and mean-reverts; HAR-RV and EWMA run beside it.", where: "vol.py" },
      { name: "Volatility target", f: "<var>L</var> = σ<sub>target</sub> / σ̂", say: "20% target by default.", where: "sizing.py · Sizing lab" },
      { name: "Kelly as an edge check", f: "<var>f</var>* = (μ − <var>r</var>) / σ<sup>2</sup>; at fraction <var>k</var>, leverage <var>L</var> needs μ − <var>r</var> = <var>L</var>σ<sup>2</sup>/<var>k</var>", say: "A 32%-volatility book at 1.5x needs about 15% a year over cash at full Kelly, 61% at quarter Kelly.", where: "sizing.py · Sizing lab" },
      { name: "Drawdown cap", f: "largest <var>L</var> with the <var>q</var>-quantile of one-year max drawdown ≤ limit", say: "2,000 simulated years, rebalanced daily, borrowing at cash plus a spread. Size to run = min(vol target, drawdown cap, gross limit).", where: "sizing.py · Sizing lab" },
    ] },
    { group: "Market reads", items: [
      { name: "What moved", f: "Δ<sub>w</sub> = <var>x</var><sub>t</sub> − <var>x</var><sub>t−7d</sub> (yields, spreads, volatility) or ln(<var>P</var><sub>t</sub>/<var>P</var><sub>t−7d</sub>) (prices); &nbsp; <var>z</var> = (Δ<sub>w</sub> − mean)/sd over every seven-day change in three years", say: "Unusual means 2σ or more. Overlapping weeks give a large sample; fat tails make 2σ weeks more common than one in 22.", where: "marketstate.py · What moved" },
      { name: "Realized volatility", f: "σ<sub>21</sub> = sd(ln <var>P</var><sub>t</sub>/<var>P</var><sub>t−1</sub>, last 21 days) × √252 × 100", say: "Close to close, in the same volatility points as VIX and VXN.", where: "marketstate.py · Is insurance cheap?" },
      { name: "Volatility risk premium", f: "VRP<sub>t</sub> = IV<sub>t</sub> − σ<sub>21,t</sub>; &nbsp; earned<sub>t</sub> = IV<sub>t</sub> − σ<sub>21,t+21</sub>", say: "The first compares today's price with the past month; the second with the month the option covered, which is what sellers actually earn.", where: "marketstate.py · Is insurance cheap?" },
      { name: "VIX term structure", f: "VIX / VIX3M; above 1 the curve is inverted", say: "Near-term fear priced above three-month fear.", where: "marketstate.py · Signals" },
      { name: "Net liquidity", f: "(WALCL − WTREGEN − 1,000 × RRPONTSYD) / 10<sup>6</sup>, in $ trillions", say: "Weekly on the Fed's Wednesday balance sheet; WALCL and WTREGEN are in millions, reverse repo in billions, taken on the same day.", where: "marketstate.py · Liquidity" },
      { name: "Funding gap", f: "SOFR − IORB, in basis points; the signal uses the five-day average", say: "Above zero, repo pays more than reserves: cash is scarce.", where: "marketstate.py · Signals" },
      { name: "Desk read", f: "score(playbook) = Σ<sub>signals</sub> [2 if red, 1 if amber or a mapped green]; closest = highest score, at least 3", say: "A tally, not a model: it says which playbook the evidence argues for, and the reader decides.", where: "views.js · Signals" },
    ] },
    { group: "Risk and validation", items: [
      { name: "VaR and expected shortfall", f: "VaR<sub>99</sub> = −quantile<sub>1%</sub>(<var>r</var>), &nbsp; ES = −mean(<var>r</var> | <var>r</var> ≤ −VaR); FHS: <var>r̃</var><sub>t</sub> = <var>r</var><sub>t</sub> · σ̂<sub>today</sub>/σ̂<sub>t</sub>", say: "Filtered history makes VaR respond to today's volatility.", where: "risk.py · Engine readout" },
      { name: "Probabilistic Sharpe", f: "PSR = Φ[(SR − SR*) √(<var>n</var>−1) / √(1 − γ<sub>3</sub>SR + (γ<sub>4</sub>−1)SR<sup>2</sup>/4)]", say: "SR per period; γ<sub>3</sub> skew, γ<sub>4</sub> kurtosis.", where: "metrics.py" },
      { name: "Deflated Sharpe", f: "SR* = √V[SR] · [(1 − γ)Φ<sup>−1</sup>(1 − 1/<var>N</var>) + γΦ<sup>−1</sup>(1 − 1/(<var>Ne</var>))], &nbsp; γ ≈ 0.5772", say: "The Sharpe the best of <var>N</var> skill-less trials would show by luck. Above 0.95 is the bar.", where: "metrics.py · Engine readout" },
      { name: "Forecast skill", f: "Brier = mean[(<var>p</var> − <var>y</var>)<sup>2</sup>], &nbsp; skill = 1 − Brier/Brier<sub>base rate</sub>", say: "A model must beat always forecasting the base rate, out of sample.", where: "signals.py" },
     ] },
    { group: "Decisions and research (v0.5)", items: [
      { name: "Velocity, acceleration, time to trigger", f: "<var>v</var><sub>13</sub> = OLS slope of the last 13 weeks, per week; <var>a</var> = <var>v</var><sub>13</sub>(<var>t</var>) − <var>v</var><sub>13</sub>(<var>t</var> − 13); <var>T</var> = (<var>L</var><sup>*</sup> − <var>L</var>)/<var>v</var> when sign(<var>v</var>) = sign(<var>L</var><sup>*</sup> − <var>L</var>)", say: "Monthly series use a four-print (three-month) slope and the one-month change. Price series are sloped in logs.", where: "roc.py · Decide desk" },
      { name: "Confidence and fragility", f: "conf = ∏ <var>p</var><sub>i</sub> over a call's assumptions; fragility<sub>i</sub> = (1 − <var>p</var><sub>i</sub>) × impact<sub>i</sub>", say: "A product assumes independence; correlated assumptions fail together, so it is a floor on the risk.", where: "decisions.py · Decide desk" },
      { name: "Kelly on a position", f: "<var>f</var><sup>*</sup> = <var>p</var>/<var>l</var> − (1 − <var>p</var>)/<var>w</var>, &nbsp; growth <var>g</var> = <var>p</var> ln(1 + <var>fw</var>) + (1 − <var>p</var>) ln(1 − <var>fl</var>)", say: "Win <var>w</var> or lose <var>l</var> per unit of position. The desk caps size at a quarter of <var>f</var><sup>*</sup>.", where: "decisions.py · Journal" },
      { name: "Luck against skill", f: "P(≥<var>k</var> of <var>n</var> | ½) = Σ<sub>i≥k</sub> C(<var>n</var>,<var>i</var>)/2<sup><var>n</var></sup>; &nbsp; alpha<sub>i</sub> = <var>r</var><sub>i</sub> − β<sub>i</sub><var>r</var><sub>bench</sub>; &nbsp; <var>n</var><sub>needed</sub> = (2·sd/mean)<sup>2</sup>", say: "Process (four checks) and outcome (alpha) are scored separately, so luck shows up as its own quadrant.", where: "decisions.py · Journal" },
      { name: "The hedge line", f: "ρ<sub>36</sub>(stocks, bonds) bucketed by π<sub>36</sub>; cut <var>c</var> maximizes share(ρ&lt;0 | π&lt;<var>c</var>) − share(ρ&lt;0 | π≥<var>c</var>); line = low edge of the cuts within 1 point of the best", say: "Monthly S&amp;P 500 total return against a constant-maturity 10-year bond, 1871 on; months filled on a full calendar.", where: "research.py · Findings" },
      { name: "Months to the line", f: "first <var>k</var> with (CPI<sub><var>t</var>+<var>k</var></sub>/CPI<sub><var>t</var>+<var>k</var>−36</sub>)<sup>1/3</sup> − 1 &lt; line, with CPI growing 2% a year after <var>t</var>", say: "Base effects included: the months that roll out of the average are the real ones.", where: "marketstate.py · Decide desk" },
      { name: "Depreciation vintages", f: "<var>D</var><sub>t</sub> = Σ<sub>v</sub> <var>C</var><sub>v</sub>[<var>s</var>·ov(<var>t</var>,<var>v</var>,<var>L</var><sub>s</sub>)/<var>L</var><sub>s</sub> + (1−<var>s</var>)·ov(<var>t</var>,<var>v</var>,25)/25], &nbsp; <var>s</var> fitted to reported <var>D</var>", say: "Each year's capex enters service mid-year; ov is the overlap of year <var>t</var> with the asset's life.", where: "fundamentals.py · Fundamentals" },
      { name: "Minsky stage", f: "hedge if capex ≤ OCF; Ponzi edge if OCF ≤ 0 or operating income &lt; interest; otherwise speculative", say: "Latest-quarter income and interest are used when the annual figures hide a recent turn.", where: "fundamentals.py · Fundamentals" },
      { name: "Compound growth with a hedge", f: "<var>g</var> = exp(Σ<sub>s</sub> <var>p</var><sub>s</sub> ln(1 + <var>r</var><sub>s</sub> − <var>c</var> + <var>h</var><sub>s</sub>)) − 1", say: "Spitznagel's test: own the hedge only if <var>g</var> rises.", where: "decisions.py · Swans" },
      { name: "Watts from dollars", f: "GW = capex/cost per GW; TWh = GW × 8,760 × load/1,000; share = TWh/4,000", say: "4,000 TWh is implied by LBNL's 176 TWh = 4.4% for 2023.", where: "Physics desk" },
    ] },
    { group: "Brain, trading and the field manual (v0.6)", items: [
      { name: "Propagation by order", f: "<var>x</var><sub>k</sub> = <var>W</var>&#8868;<var>x</var><sub>k−1</sub>; total = Σ<sub>k≤K</sub> <var>x</var><sub>k</sub> → [(<var>I</var> − <var>W</var>&#8868;)<sup>−1</sup> − <var>I</var>]<var>x</var><sub>0</sub> when ρ(<var>W</var>) &lt; 1", say: "Eleven links measured by recursive regression on standardized monthly changes per regime; the rest judged. 400 Monte Carlo draws over every link's uncertainty.", where: "brain.py · The brain" },
      { name: "Avellaneda-Stoikov quotes", f: "<var>r</var> = <var>s</var> − <var>q</var>γσ<sup>2</sup>τ, &nbsp; δ = γσ<sup>2</sup>τ + (2/γ) ln(1 + γ/<var>k</var>)", say: "Fills at rate <var>A</var>e<sup>−<var>k</var>δ</sup>; the simulator compares the skewed quoter with a symmetric one on the same paths.", where: "microstructure.py · Market making" },
      { name: "Square-root impact and Almgren-Chriss", f: "<var>I</var> = <var>Y</var>σ√(<var>Q</var>/ADV); &nbsp; <var>x</var><sub>j</sub> = <var>X</var> sinh(κ(<var>T</var> − <var>t</var><sub>j</sub>))/sinh(κ<var>T</var>)", say: "Linear temporary impact is calibrated so the even pace costs exactly the square-root impact.", where: "microstructure.py · Market making" },
      { name: "Hedge selector", f: "ES<sub>5%</sub>(book) − ES<sub>5%</sub>(book + 0.3·hedge), per regime; ratio to yearly carry when carry is a cost", say: "Regimes: 36-month inflation above or below the 2.75% line.", where: "buyside.py · Buyside 2026" },
      { name: "Student-t shortfall", f: "ES<sub>α</sub> = −[μ − <var>s</var> · <var>f</var><sub>ν</sub>(<var>t</var><sub>α</sub>)/(1 − α) · (ν + <var>t</var><sub>α</sub><sup>2</sup>)/(ν − 1)]", say: "ν, μ and <var>s</var> fitted by maximum likelihood; compared with the normal model and history at 97.5%.", where: "buyside.py · Buyside 2026" },
      { name: "Private credit net yield", f: "net = (base + spread − PD·(1 − R) − mgmt)·(1 − incentive)", say: "Reproduces the manual's table: about 6.4% at 2% defaults, 4.5% at 6%, negative at 14%.", where: "accounting.py · Buyside 2026" },
      { name: "Feed heat and skew", f: "heat = (<var>n</var><sub>24h</sub> − μ<sub>28</sub>)/max(σ<sub>28</sub>, √(μ<sub>28</sub> + 1)); skew = share<sub>niche</sub>(theme, 72h) − share<sub>niche</sub>(all)", say: "Lead time: the lag of peak cross-correlation between niche and mainstream counts.", where: "feeds.py · Noteworthy" },
    ] },
  ];

  const FAQ = [
    { g: "v0.7", q: "Is the solver a forecast?", a: "No. It turns stated assumptions (scenarios, their priors and the likelihood of each signal) into a choice that respects your loss limit, and shows which assumption moves that choice. The scenarios and likelihoods are labelled Assumed and Hypothesis; the signals are Observed; covariances are Estimated." },
    { g: "v0.7", q: "Why does the solver hold less equity than the engine's size?", a: "Different questions. The engine sizes the equity book to a volatility target and a drawdown cap. The solver asks what keeps the worst of seven 3-month scenarios inside a loss limit while growing fastest. With a 15% limit and a liquidity crash on the list, the full book fails; the solver cuts equity, adds put spreads and gold, and says which signal would change that." },
    { g: "v0.7", q: "What is game theory doing in a risk tool?", a: "Other players set the prices the book lives on. The builders' capex race explains why returns on capacity fall even when demand is strong; the crowded-exit game gives the threshold at which a crowded trade runs; Kyle's model prices what your own order reveals. Each is solved exactly and labelled with its assumptions." },
    { g: "The project", q: "What is this, in one sentence?", a: "A risk desk for a concentrated AI-buildout equity book: it measures when long Treasuries hedge that book, prices the alternatives, and sizes positions so a bad year is survivable." },
    { g: "The project", q: "Does it predict returns?", a: "No, on purpose. It forecasts risk (volatility, correlation, drawdown) because those forecasts are reliable. Its one return model runs walk-forward and is judged on calibration; in the planted test it finds an edge only where one exists." },
    { g: "Decisions", q: "Why does the desk say bonds will not hedge?", a: "Because stocks and bonds are moving together today: the stock-bond state is the gate that binds. The inflation finding is weaker than the headline once was: the line chosen on data through 2016 is 4.25%, a bootstrap puts it anywhere from 2.75% to 4.25%, and today's 3.06% sits inside that band. Out of sample since 1901, adding the inflation gate to the correlation rule did not improve the worst months." },
    { g: "Decisions", q: "Why did the inflation figures change in v0.5?", a: "The federal shutdown meant BLS published no CPI for October 2025. Code that drops the missing month and shifts by 12 rows silently measures 13 months of inflation: August 2026 read 3.69% instead of the 3.4% BLS published. The engine now builds a full monthly calendar and fills a one-month gap geometrically, and prefers BLS and the Treasury's 10-year over Shiller's preliminary last months. The September print (3.7% on Oct 14) is in." },
    { g: "Decisions", q: "How is a decision's confidence computed?", a: "As the product of the probabilities of the assumptions it rests on, each written down with its evidence and the test that would falsify it. Move an assumption's slider and every decision that uses it updates. A product assumes independence; assumptions that fail together make it a floor on the risk." },
    { g: "Decisions", q: "How does the journal tell luck from skill?", a: "Four ways: a Brier score and calibration chart for the stated odds; alpha after the market's share (return minus beta times the benchmark); a binomial test of the hit rate against a coin flip; and a two-by-two of process against outcome, so a good result from a bad process is labeled luck." },
    { g: "Decisions", q: "Where are my journal entries stored?", a: "In the published page, in your own private space on the artifact: no one else can read it, the owner included. Opened anywhere else, in this browser's storage. Export writes a JSON file that the engine scores with python -m buildout journal." },
    { g: "Decisions", q: "Why rates of change rather than levels?", a: "Markets price the change before it shows in the level. The Findings desk measures it: since 1880, the next year's real return averaged 11.6% when earnings growth was negative and slowing, against 6.2% when it was positive and speeding up. Every signal shows its velocity, acceleration and time to its rule's line." },
    { g: "Decisions", q: "Are the findings data-mined?", a: "The hedge line is now chosen only on data before an untouched final decade, walked forward in 20-year blocks, and bootstrapped in 36-month blocks that re-choose the cut each time; the engine can return no reliable threshold, and the policy then drops the inflation gate. The deflated Sharpe counts every variant, hedge policy and candidate hedge tried, not only the four on display. Small samples (9 oil shocks, 16 VIX spikes) remain direction, not law." },
    { g: "The project", q: "Is this investment advice?", a: "No. It is a research tool. The book is a model book, the theses are research positions with written kill criteria, and every tool input is an assumption to stress." },
    { g: "The project", q: "Who is it for?", a: "Anyone running concentrated equity risk who has leaned on bonds as the hedge: a portfolio manager, an allocator, or an individual with a large technology position." },
    { g: "Data", q: "Where does the data come from, and what does it cost?", a: "FRED, free, for rates, credit, volatility, oil and the Nasdaq-100 back to 1986. Databento, pay as you go, for daily bars, corporate actions and CME futures. SEC EDGAR, free, for capex and cash flow. Kalshi, free, for event odds. Only derived analytics are stored; raw market data never enters git." },
    { g: "Data", q: "How fresh is it?", a: "The daily run fires before the US open, Tuesday to Saturday, so it reads the prior close. Every live number carries its date, and the page flags anything more than three weekdays old." },
    { g: "Data", q: "What happens when a source fails?", a: "Each FRED series downloads on its own; a failure is recorded and the run continues without it. A status file lists every check and the Engine desk shows it. An invalid file shows an error on its own panel without breaking the rest of the page." },
    { g: "Data", q: "Why FRED's 20-year yield instead of TLT prices?", a: "History. TLT starts in 2002; the 20-year yield runs back to 1993 and lets the engine test the hedge through the 1994 rout, 2000, 2008, 2020 and 2022. The book run uses TLT itself once Databento data is in." },
    { g: "Method", q: "Why a 63-day half-life for the correlation?", a: "About one quarter: fast enough to catch a regime turn within weeks, slow enough not to chase noise. The one-year rolling correlation sits beside it as the slow read." },
    { g: "Method", q: "Why the ±0.10 band and hysteresis?", a: "A hedge that flips on and off around zero pays costs and is right half the time. The engine turns the bond hedge on only once correlation is clearly negative, and off once it turns positive." },
    { g: "Method", q: "Why long-only hedge ratios?", a: "The question is whether to hold bonds as insurance, not whether to short them against stocks. That is a different trade with its own risk." },
    { g: "Method", q: "Why minimum-variance and not a fixed 30%?", a: "The fixed hedge is the benchmark to beat. In the inflation regime it kept buying bonds while they fell with stocks. In the synthetic test the regime-gated ratio cut variance 5.0% while the fixed hedge added 0.6%." },
    { g: "Method", q: "Why Black-Scholes when the market has skew?", a: "It is the common language for Greeks and a clean baseline. The tail-budget tool lets you raise implied volatility at the strike to reflect skew, the implied-volatility solver reads it back from a market price, and the roadmap replaces assumed volatility with listed option chains." },
    { g: "Method", q: "Why size with risk limits and use Kelly only as a check?", a: "Kelly needs the expected return, the input known least: halve the edge and the Kelly bet halves. Volatility targets and drawdown caps need only volatility, which forecasts well. Kelly then asks whether the return you believe in justifies the size the limits allow." },
    { g: "Method", q: "How realistic is the drawdown simulation?", a: "It is a floor. It assumes normal daily returns and daily rebalancing; real markets gap and have fat tails, so real drawdowns at the same leverage are worse. That is why the cap uses the 95th percentile and the gross limit stays at 1.5x." },
    { g: "Method", q: "What is the deflated Sharpe ratio, and why use it?", a: "The probability that a backtest's Sharpe is real after charging for how many variants were tried and for skew and fat tails. With four policies tried, the best one has to clear a higher bar than its raw Sharpe suggests." },
    { g: "Results", q: "What is the backtest Sharpe?", a: "The live book panel reports it beside the deflated Sharpe once the Databento key is in. The synthetic tests prove the machinery recovers planted answers; by design they say nothing about markets." },
    { g: "Results", q: "How do you know the backtest is not cheating?", a: "A canary. A signal known at today's close earns nothing on a random walk (Sharpe 0.28), while a signal that peeks one day ahead posts a Sharpe of 21. If timing ever leaked, the canary would fail the build." },
    { g: "Results", q: "What has the data said about bonds as a hedge since 2022?", a: "That they stopped being reliable. The Fed's own measure was +0.21 on Jul 31, 2026. Bonds still rallied in growth scares, as on Oct 8, 2026, but fell with stocks in inflation and supply shocks: March 2026 and the week of Apr 7, 2025." },
    { g: "Markets", q: "Why do stocks and bonds sometimes fall together?", a: "When inflation or bond supply drives rates, higher yields hit both: bonds directly and stocks through higher discount rates. When growth drives markets, falling yields cushion stocks. The sign of the correlation tracks which shock dominates." },
    { g: "Markets", q: "If not bonds, what hedges the book?", a: "Contracts, not correlations: index put spreads for fast drawdowns, credit protection for an AI financing break, energy for an oil shock, and lower gross through volatility targeting. The hedge matrix grades fifteen candidates across six scenarios." },
    { g: "Markets", q: "What does tail protection cost?", a: "Rolling 85%-strike puts on the whole book at 30% implied volatility costs about 3.4% of NAV a year in the tail-budget tool, and a −35% quarter then pays about 20%. Put spreads cut the cost by giving up the deepest tail." },
    { g: "Markets", q: "Why does an insurer's balance sheet matter to an equity book?", a: "Insurers are the marginal buyers of the long-dated debt that funds data centers; Meta's Hyperion bonds went to PIMCO, which Allianz owns. If their appetite slows, AI financing costs rise: the lane where bonds fail as a hedge." },
    { g: "Markets", q: "What is the curve paying for duration right now?", a: "On the Oct 19 curve, a financed 2-year earns about 0.76% a year from carry and roll-down and can absorb a 79bp rise; a 30-year earns about 1.0% and absorbs only 7bp, because the 20-year kink makes it roll up the curve, not down. Per unit of risk, the front end is where carry is." },
    { g: "Markets", q: "What is the single most important insight here?", a: "A bond hedge is a bet on which kind of selloff comes next. Measure the regime every day, and buy protection that pays regardless of the cause." },
    { g: "Market reads", q: "What is the desk read, and how is it computed?", a: "A one-line summary above the signals board. Each signal maps its amber or red state to the playbook it argues for; the read adds the votes, red counting twice, and names the closest playbook once it has three or more. It is a tally, not a model." },
    { g: "Market reads", q: "Why can bonds hedge in a week while the regime says they amplify?", a: "The regime is a 63-day average and a week can go the other way. From Oct 13 to Oct 16, the 30-year yield fell 13bp while the Nasdaq-100 dropped on AI credit worries: a growth-and-credit scare inside an inflation regime. The rule holds no bond hedge until the correlation crosses −0.10, so one good week does not flip it." },
    { g: "Market reads", q: "How do I know whether puts are cheap right now?", a: "Compare implied volatility with its own history and with realized. The Options desk ranks VXN against ten years and against the Nasdaq-100's realized volatility; cheap is the bottom third with a small premium. The VIX curve adds timing: when it inverts, stress is already priced." },
    { g: "Market reads", q: "What does an inverted VIX curve mean for a hedger?", a: "The market prices the next month as more dangerous than the next three. It shows up in sharp selloffs and is usually the worst moment to buy protection and a good one to start monetizing it. The engine counts the inverted days in the past year." },
    { g: "Market reads", q: "What is net liquidity, and does it drive stocks?", a: "Fed assets minus the Treasury's cash account minus reverse repo: the cash the Fed leaves in the private system. It is an accounting identity, not a law of prices. The desk uses it to see who is draining cash and how close reserves are to scarce, not to time the index." },
    { g: "Market reads", q: "Why watch SOFR against IORB?", a: "Banks can earn IORB at the Fed without risk, so repo should trade a little below it while reserves are ample. Repo above IORB means cash is scarce. In September 2019 repo rates spiked and the Fed had to add cash; in October 2025 it cited money-market conditions when it decided to stop shrinking its balance sheet." },
    { g: "Market reads", q: "Why does the CCC spread matter when high yield looks calm?", a: "The weakest borrowers feel tight money first. On Oct 16 the broad high-yield spread was about 3.3%, tight by history, while CCC and lower paid 12.97%, up from 8.53% in July 2025: stress concentrated at the bottom of the ratings, where thesis 6 expects private-credit losses to surface." },
    { g: "Market reads", q: "Why is the yen in the table?", a: "The yen funds global carry trades. A sharp yen rally forces them to unwind, as in August 2024, when the Nikkei fell 12.4% in a day. The table flags an unusual weekly yen move before it reaches volatility." },
    { g: "Market reads", q: "Is a 2σ week rare?", a: "Under a normal distribution about one week in 22 is a 2σ move. Market changes have fat tails, so they come more often: treat 2σ as worth a look and 3σ as news." },
    { g: "Data", q: "Why do the credit spread charts start in 2023?", a: "Since April 2026 FRED carries only the last three years of the ICE BofA spread indices; older history is licensed from ICE. The engine reads what FRED has, so the episode atlas shows credit moves only for recent episodes." },
    { g: "Implementation", q: "How would you put the hedge on?", a: "TLT for simplicity, or ZB and UB futures matched in DV01 to keep cash free; index put spreads on QQQ or NDX for convexity; HYG puts or CDX HY for credit. The futures calculator sizes the contracts." },
    { g: "Implementation", q: "How often would you rebalance?", a: "Daily signals, banded trades. The hedge ratio and gross update every day, but positions trade only when they leave a band (the 20% trim rule), which keeps costs and noise down." },
    { g: "Implementation", q: "What would you add with more resources?", a: "Listed option chains for real skew, intraday data for execution and liquidity, positioning data (CFTC, dealer gamma), and a paper-trading log that scores the desk against its own forecasts." },
    { g: "Engineering", q: "What is the stack?", a: "Python (numpy, pandas, scipy) for the engine, one self-contained HTML page with no framework, GitHub Actions for the daily run, and JSON files as the contract between them." },
    { g: "Engineering", q: "How is the page tested?", a: "Its bond, curve and option math runs in Node against the Python engine on every push, agreeing to about 1e−9, and property tests throw thousands of random bonds, curves and options at the engine (they found two real bugs). A browser suite feeds the page hostile and truncated files, hundreds of random inputs, clicks and resizes, every width from 320 to 1920 pixels, a full print and an accessibility audit; any script error, broken number on screen, sideways scroll or serious accessibility issue fails it." },
    { g: "Engineering", q: "How do I add a ticker or a thesis?", a: "Tickers and weights live in config.toml (priors for short histories too); theses live in site/src/data.js. Run the tests, run scripts/assemble_page.py, push." },
    { g: "v0.6", q: "What does the brain actually compute?", a: "It treats the system as a signed network: a shock at one node travels link by link, and the desk adds up what arrives at each order. Eleven links are measured from monthly data in two regimes; the rest are judged and editable. On top it finds the strongest channels, the feedback loops, the single link the answer depends on most, the share of 400 random worlds where the answer keeps its sign, and the cheapest combination of driver shocks that produces a given outcome." },
    { g: "v0.6", q: "What is the most important thing the brain measured?", a: "The sign of the link from the 10-year yield to stocks. From 1990 to 2021 a 1σ rise in yields came with stocks up 0.11σ the same month: rising yields meant good growth news. Since 2022 the same move comes with stocks down 0.24σ. That flip is why a long-bond hedge fails today." },
    { g: "v0.6", q: "How does the Noteworthy scraper find asymmetric information?", a: "It reads niche Substacks, a Telegram wire, X accounts (with an API token), Reddit, Hacker News and official feeds every morning, tags each item with themes, and scores each theme: heat against its own history, how much of the talk comes from niche sources, and, once three weeks of history exist, how many days the niche sources lead the mainstream." },
    { g: "v0.6", q: "Why not scrape X directly?", a: "X's terms forbid it. The engine uses the official API when an X_BEARER_TOKEN secret is set and skips X cleanly otherwise. Telegram public channels publish a web preview at t.me/s/<channel>, which is fine to read." },
    { g: "v0.6", q: "Where did the field manual and the data disagree?", a: "Brent (the manual quoted early-September futures; physical crude traded about $27 higher by mid-October), the real yield (1.6% is backward-looking: 10-year minus CPI; TIPS paid 2.74%), and the stock-bond correlation (+0.40 versus the engine's +0.15 and the Fed's +0.21, all positive). The rest agree." },
    { g: "v0.6", q: "Why does the challenge simulator's pass rate jump around?", a: "Because the rules are discrete. Above a certain risk per trade, one day of losses breaches the daily limit, and the number of winning trades needed to reach the target falls one whole trade at a time. The risk that maximizes the pass rate sits just below such a step." },
    { g: "v0.6", q: "Is market making just collecting the spread?", a: "No. The spread pays for adverse selection and inventory risk. The simulator shows that skewing quotes for inventory gives up a little average profit for much less risk, and the adverse-selection tool shows why uninformed retail flow is worth paying for." },
  ];

  METHODS.push({ group: "The solver, game theory and the policy contract (v0.7)", items: [
    { name: "Tempered Bayes", f: "π<sub>s</sub> ∝ prior<sub>s</sub> · Π<sub>drivers d</sub> exp(mean<sub>i∈d</sub> ln L<sub>i</sub>(o<sub>i</sub> | s))", say: "Seven signals, seven 3-month scenarios. Signals that share a driver are averaged, not multiplied, so one cause is counted once. Likelihoods are hypotheses, published on the page.", where: "reasoner.py · Solve" },
    { name: "Constrained growth search", f: "max Σπ<sub>s</sub> ln(1 + R<sub>s</sub>) s.t. min R<sub>s</sub> ≥ −L, e(1 + h) + g ≤ 2, premium ≤ budget", say: "Exhaustive over 18,414 portfolios (equity, TLT ratio, put-spread premium, gold); exact on the grid. Keep, reduce, hedge and optimal are compared on the same scenarios with regret.", where: "reasoner.py · Solve" },
    { name: "Game against Nature", f: "max<sub>x</sub> min<sub>s</sub> Σ x<sub>i</sub>R<sub>i,s</sub> by linear programming", say: "Simplex with Bland's rule; Nature's equilibrium scenario mix is the dual.", where: "reasoner.py · Solve" },
    { name: "Value of information", f: "EVSI<sub>j</sub> = Σ<sub>o</sub> P(o) max<sub>a</sub> E[U | o] − max<sub>a</sub> E[U]", say: "Each signal removed from the evidence and re-observed on and off; also whether flipping it changes the choice.", where: "reasoner.py · Solve" },
    { name: "Reverse stress", f: "s* = −L Σb/(b′Σb), d = L/√(b′Σb)", say: "Covariances of S&P 500, 10-year yield, Brent and gold changes, measured by regime and scaled to three months; the AI factor's 25% volatility is assumed.", where: "reasoner.py · Solve" },
    { name: "Nash equilibria", f: "pure: mutual best responses; mixed: A<sub>I,J</sub>y = v1, x′B<sub>I,J</sub> = u1′ on equal supports", say: "Support enumeration, exact for nondegenerate games; dominance, Pareto cells and the price of anarchy alongside.", where: "games.py · Games" },
    { name: "Asymmetric Cournot", f: "q<sub>i</sub> = (a − (N+1)c<sub>i</sub> + Σc<sub>j</sub>)/(b(N+1)); P = (a + Σc)/(N+1)", say: "a and b calibrated so the equilibrium reproduces observed capex at an assumed return on capacity; c<sub>i</sub> = 1/server life + cost of capital.", where: "games.py · Games" },
    { name: "Global game", f: "E[θ | x*] − λΦ(√β(x* − μ*)/√(1 + β/(α+β))) = −c", say: "Bisection; uniqueness checked by the monotonicity of the indifference curve. λ from square-root impact of the crowd.", where: "games.py · Games" },
    { name: "Hedge line, out of sample", f: "cut chosen on data before the last 120 windows; walk-forward by 20-year blocks; circular block bootstrap (blocks of 36 months)", say: "Status ok, no_reliable_threshold or insufficient_evidence; only ok carries a line into the policy.", where: "research.py · Findings" },
    { name: "One NAV convention", f: "r<sub>t</sub> = NAV<sub>t</sub>/NAV<sub>t−1</sub> − 1, NAV<sub>−1</sub> = 1, costs and financing inside NAV", say: "Inception cost in the first return; Sharpe in excess of accrued cash; next-session execution; every variant on the same dates; a cash-only baseline.", where: "analytics/backtest.py · Engine" },
  ] });

